import { fetchGraphQl } from '../fetch-graphql';
import { GET_STORE_CONFIG } from './graphql/getStoreConfig.graphql';
import { handleNetworkError } from '@/b2b-quick-order/lib/network-error';
import { handleFetchError } from '@/b2b-quick-order/lib/fetch-error';

export const getStoreConfig = async (): Promise<{
  storeConfig: {
    quickOrderActive: boolean;
  };
}> => {
  return await fetchGraphQl(GET_STORE_CONFIG, {
    method: 'GET',
    cache: 'force-cache',
  })
    .then((response) => {
      if (response.errors?.length) return handleFetchError(response.errors);

      return {
        storeConfig: {
          quickOrderActive:
            response?.data?.storeConfig?.quickorder_active ?? false,
        },
      };
    })
    .catch(handleNetworkError);
};
