import { Initializer } from '@adobe-commerce/elsie/lib';
import { Lang } from '@adobe-commerce/elsie/i18n';
import { getStoreConfig } from '@/b2b-quick-order/api';

type ConfigProps = {
  langDefinitions?: Lang;
  quickOrderActive?: boolean;
};

export const initialize = new Initializer<ConfigProps>({
  init: async (config) => {
    const defaultConfig: Partial<ConfigProps> = {
      quickOrderActive: false,
    };

    try {
      const storeConfigResponse = await getStoreConfig();
      defaultConfig.quickOrderActive =
        storeConfigResponse.storeConfig.quickOrderActive;
    } catch (error) {
      console.error('[Quick Order] Failed to fetch store config:', error);
    }

    initialize.config.setConfig({ ...defaultConfig, ...config });
  },

  listeners: () => [],
});

export const config = initialize.config;
